// Cuestionarios por módulo y por público (t = docentes, a1 = 12–14, a2 = 15–18).
// Pregunta: [texto, [opción, opción, opción], índiceDeLaCorrecta, explicación]
QZ.es=[
// 1 — ¿Qué es la salud mental?
{t:[
["Un alumno que suele estar alegre lleva una semana retraído. Según el modelo del continuo, ¿cuál es la lectura más útil?",["Se ha trasladado de forma permanente a la zona roja","Su zona puede estar cambiando, así que conviene hablar con él en privado y con calma","Los estados de ánimo son algo personal; lo mejor es no intervenir"],1,"Las zonas fluctúan con el tiempo. Una conversación tranquila y privada respeta al alumno y mantiene abierta la puerta."],
["¿Por qué ofrecer prácticas universales (registros anónimos, tablas de zonas, menús de afrontamiento) a toda la clase?",["Para identificar qué alumnos tienen un trastorno","Para sustituir el apoyo profesional","Para crear un lenguaje común y normalizar la fluctuación para todos"],2,"Las prácticas universales integran la conciencia emocional en la cultura del centro sin señalar a nadie."],
["¿Qué afirmación se ajusta mejor al modelo del continuo?",["Las zonas son rasgos de personalidad fijos","Todas las personas se mueven entre zonas a lo largo del tiempo","La zona amarilla significa que la persona tiene un trastorno"],1,"El bienestar de cada persona fluctúa; ninguna zona es permanente."]],
a1:[
["¿Qué significa la zona verde?",["Que nunca debes sentirte triste","Que en general te sientes bien y estás afrontando las cosas","Que estás en apuros"],1,"Verde significa sentirte bien y saber afrontar las cosas. Puedes tener momentos tristes estando en verde."],
["Notas que estás en la zona amarilla antes de un examen. ¿Qué podría ayudarte?",["Respirar despacio o hablar con alguien de confianza","Hacer como si no pasara nada","Quedarte en tu cuarto todo el día"],0,"Las herramientas de afrontamiento y hablar con alguien pueden ayudarte a volver hacia el verde."],
["«Si hoy estoy en la zona roja, me quedaré ahí para siempre». ¿Qué es verdad?",["Las zonas y las emociones cambian con el tiempo","Para algunas personas es permanente","Nada puede cambiarlo"],0,"Ningún estado emocional es permanente. La ayuda y el tiempo marcan la diferencia."]],
a2:[
["¿En qué se diferencia el enfoque del continuo de una división simple entre «sano» y «enfermo»?",["Dice que la salud mental se mueve a lo largo de un espectro para todas las personas","Dice que solo algunas personas tienen salud mental","Dice que las zonas nunca cambian"],0,"La salud mental es dinámica. Todas las personas se mueven por el continuo según el contexto y el apoyo que reciben."],
["Un amigo lleva semanas en la zona amarilla, con cambios en el sueño y el apetito. ¿Cuál es una buena respuesta?",["Decirle que se endurezca","Esperar a que empeore","Invitarle a hablar, escucharle y animarle a buscar apoyo"],2,"Escuchar sin juzgar y animar a buscar apoyo ayuda antes de que la situación se agrave."],
["¿Por qué los registros emocionales suelen ser anónimos?",["Reducen el miedo a ser juzgado y fomentan una reflexión sincera","Para ocultar los resultados a todo el mundo para siempre","No están pensados para tomarse en serio"],0,"El anonimato reduce el estigma y facilita la autorreflexión sincera."]]},
// 2 — Malestar frente a trastorno
{t:[
["¿Qué situación sugiere que un alumno puede necesitar una atención más cercana?",["Un mal humor tras perder un partido","Nerviosismo antes de una presentación","Ánimo bajo y pérdida de interés durante semanas que afectan a los estudios y las amistades"],2,"La duración, la intensidad y el impacto en la vida diaria distinguen el malestar normal de lo que requiere más atención."],
["¿Cuál es el papel del docente al notar estas señales?",["Diagnosticar e informar a la clase","Observar, hablar con cuidado y poner al alumno en contacto con orientación o con su familia","Esperar al final del trimestre"],1,"Los docentes no diagnostican. Observan, escuchan y conectan al alumnado con el apoyo adecuado."],
["¿Qué afirmación sobre el malestar emocional es correcta?",["Es una respuesta normal ante los retos y suele aliviarse","Siempre es un trastorno","Nunca necesita apoyo"],0,"El malestar es común y a menudo pasajero, pero el apoyo igualmente puede ayudar."]],
a1:[
["Sentirte muy nervioso antes de un examen es, lo más probable...",["Estrés normal","Siempre un problema grave","Algo que hay que esconder"],0,"El estrés ante los retos es normal. Respirar y planificar puede ayudar."],
["¿Cuál es una señal de que deberías contárselo a un adulto de confianza?",["Estar molesto después de perder una partida","Sentirte muy triste casi todos los días durante semanas y no disfrutar de nada","Estar cansado después de hacer deporte"],1,"Las emociones que duran semanas y dificultan la vida diaria merece la pena compartirlas."],
["Un amigo está triste un día después de una discusión. ¿Qué ayuda más?",["Reírte de él","Decirle a todo el mundo que tiene un trastorno","Ser amable y escucharle"],2,"Ser amable y escuchar siempre ayuda, y la tristeza después de una discusión es normal."]],
a2:[
["¿Qué factores ayudan a distinguir el malestar de un trastorno?",["La duración, la intensidad y el impacto en el funcionamiento diario","Solo el aspecto de la persona","Solo la frecuencia con la que publica en internet"],0,"Fijarse en cuánto dura, cuán fuerte es y cuánto interfiere en la vida da una imagen más completa."],
["Un compañero está estresado en época de exámenes, pero sigue durmiendo, comiendo y quedando con amigos. Lo más probable es que sea...",["Un trastorno que necesita tratamiento","Una respuesta de estrés normal, aunque las herramientas de afrontamiento pueden ayudar","Nada, así que nunca hace falta apoyo"],1,"El estrés es común. El funcionamiento diario se mantiene en gran parte, pero las estrategias de afrontamiento siguen ayudando."],
["¿Por qué evitar decirle a un amigo, sin darle importancia, «estás deprimidísimo»?",["Porque solo los profesionales diagnostican, y las etiquetas casuales banalizan y estigmatizan","Porque los amigos nunca están tristes","Porque las palabras nunca importan"],0,"Las etiquetas casuales pueden hacer daño y desanimar a las personas a buscar ayuda de verdad."]]},
// 3 — Emociones y autoconciencia
{t:[
["¿Por qué enseñar granularidad emocional?",["Las palabras precisas ayudan al alumnado a comprender y regular lo que siente","Hace que los alumnos sientan menos","Sustituye la necesidad de conversar"],0,"Cuanto más precisamente nombramos una emoción, mejor podemos comprenderla y manejarla."],
["Un alumno dice «me siento mal». ¿Qué pregunta de seguimiento es más útil?",["«No digas tonterías.»","«¿Se parece más a nervioso, decepcionado o solo?»","«Todo el mundo se siente mal a veces.»"],1,"Ofrecer opciones ayuda a convertir una etiqueta amplia en algo más preciso."],
["¿Cómo debe usarse una rueda de las emociones?",["Para diagnosticar al alumnado","Para clasificar las emociones en buenas o malas","Para afinar sentimientos generales en palabras más precisas"],2,"Las ruedas de emociones son herramientas de vocabulario, no de diagnóstico."]],
a1:[
["En lugar de «mal», ¿qué palabra puede ser más precisa?",["Decepcionado","Me da igual","Nada"],0,"Palabras precisas como decepcionado, nervioso o solo te ayudan a entenderte."],
["¿Por qué fijarse en las sensaciones del cuerpo?",["Siempre son aleatorias","Un corazón acelerado o un nudo en el estómago pueden darte pistas sobre lo que sientes","Nunca importan"],1,"Tu cuerpo suele mostrar las emociones antes de que puedas ponerles nombre."],
["¿Qué es un detonante?",["Un secreto","Algo que desencadena una emoción","Un tipo de comida"],1,"Los detonantes son hechos o situaciones que despiertan una emoción."]],
a2:[
["¿Por qué ayuda distinguir «frustrado» de «abrumado»?",["Requieren respuestas distintas","Son exactamente lo mismo","Solo los docentes necesitan saberlo"],0,"La frustración puede pedir un nuevo enfoque; sentirse abrumado puede pedir bajar el ritmo o buscar apoyo."],
["La granularidad emocional se asocia con...",["Sentir menos","Una mejor regulación emocional y comunicación","Evitar las emociones"],1,"Las personas que nombran las emociones con precisión tienden a regularlas y comunicarlas mejor."],
["¿Qué incluye un registro de emoción y detonante?",["La emoción, lo que pasó justo antes y alguna señal corporal","Solo el color de la emoción","Solo una nota"],0,"Relacionar la emoción, el detonante y la señal corporal fortalece la autoconciencia."]]},
// 4 — Dificultades frecuentes
{t:[
["Un alumno parece «vago»: no entrega tareas, está cansado y ha perdido el interés. ¿Cuál es un primer paso empático?",["Ponerle un castigo","Considerar posibles causas internas y hablar con él en privado sin juzgar","Contárselo a la clase"],1,"La conducta puede reflejar depresión, ansiedad u otras dificultades. La curiosidad va antes que el juicio."],
["La distracción relacionada con el TDAH se entiende mejor como...",["Mala educación","Una diferencia en la regulación de la atención, no una falta de esfuerzo","Falta de inteligencia"],1,"Se trata de regulación de la atención, no de fuerza de voluntad ni de modales."],
["¿Qué es adecuado si notas posibles señales de un trastorno de la conducta alimentaria?",["Comentar el peso del alumno","Evitar comentarios sobre el peso y la comida y conectar al alumno con apoyo","Ignorarlo"],1,"No diagnostiques ni comentes el peso. Conecta al alumno con el apoyo adecuado."]],
a1:[
["Alguien es muy especial con la comida y se salta comidas. ¿Cuál es una respuesta amable?",["Burlarte de él","No juzgar, ser amable y contárselo a un adulto de confianza si te preocupa","Obligarle a comer"],1,"La amabilidad y avisar a un adulto de confianza es más seguro que presionar o hacer bromas."],
["La ansiedad puede sentirse como...",["Un corazón acelerado y preocupaciones difíciles de apagar","Ser vago","No tener emociones"],0,"La ansiedad suele tener señales en el cuerpo y preocupaciones que no se detienen."],
["¿Se puede saber desde fuera si alguien tiene depresión?",["Sí, siempre","No, muchas señales están por dentro","Solo por sus notas"],1,"Lo que vemos no siempre muestra lo que alguien siente por dentro."]],
a2:[
["¿Qué patrón puede sugerir depresión en lugar de pereza?",["Sentirte cansado una vez tras trasnochar","Agotamiento persistente, pérdida de interés y desesperanza durante semanas","Tomarte un descanso del estudio"],1,"Los cambios persistentes en la energía, el interés y el ánimo durante semanas merecen atención y apoyo."],
["Un amigo te confía que lo está pasando mal. ¿Cuál es la mejor respuesta?",["Escucharle sin juzgar, darle las gracias y animarle a buscar apoyo profesional","Decirle «anímate, hombre»","Contárselo a toda la clase"],0,"Escuchar, respetar la privacidad y animar a pedir ayuda son los pasos clave."],
["¿Por qué evitar intentar diagnosticar a los amigos?",["Porque solo los profesionales cualificados pueden hacerlo; nuestro objetivo es la sensibilización y la empatía","Porque la salud mental no es real","Porque los amigos nunca se ven afectados"],0,"Construimos comprensión y apoyo; el diagnóstico corresponde a los profesionales."]]},
// 5 — Estigma y petición de ayuda
{t:[
["¿Qué respuesta facilita que un alumno se abra?",["«Estás exagerando.»","«Rápido, dime qué te pasa.»","Con calma y curiosidad: «Estoy aquí, tómate tu tiempo.»"],2,"Un tono tranquilo y sin prisa transmite seguridad."],
["El silencio ante los problemas se entiende mejor como...",["Terquedad","Autoprotección cuando pedir ayuda no resulta seguro","Falta de interés"],1,"Las personas pueden callar por miedo a ser juzgadas, por preocupaciones de privacidad o por sentir que deben salir adelante solas."],
["Un alumno te cuenta algo preocupante. ¿Qué debes hacer?",["Prometer mantenerlo totalmente en secreto","Escuchar, no prometer un secreto que no puedes guardar y conectarle con apoyo según tu protocolo","Cambiar de tema"],1,"Sé honesto sobre lo que debes compartir y sigue los pasos de protección del centro."]],
a1:[
["Pedir ayuda es...",["Una debilidad","Una fortaleza y una habilidad que se puede aprender","Solo para adultos"],1,"Pedir ayuda es de valientes y se hace más fácil con la práctica."],
["Un amigo te cuenta algo preocupante. ¿Cuál es un buen primer paso?",["Escucharle, decirle que te importa y animarle a contárselo a un adulto de confianza","Quitarle importancia riéndote","Contárselo a todo el mundo"],0,"Apoya a tu amigo y cuenta con un adulto de confianza."],
["¿Qué reacción cierra la puerta a que alguien se abra?",["«Deja de hacer drama.»","«Gracias por contármelo.»","«Estoy aquí para escucharte.»"],0,"Las respuestas despectivas hacen que sea menos probable que alguien vuelva a pedir ayuda."]],
a2:[
["¿Qué creencia es un obstáculo frecuente para pedir ayuda?",["«Debería poder con todo yo solo.»","«Hay apoyo disponible.»","«Los demás me entienden.»"],0,"Mucha gente calla porque cree que debe salir adelante sola."],
["¿Cómo podemos replantear la fortaleza?",["No necesitar nunca a nadie","Reconocer los propios límites y buscar apoyo es una habilidad","Esconder las emociones"],1,"Saber cuándo pedir ayuda es señal de madurez."],
["¿Cómo puedes apoyar a alguien sin presionarle?",["Darle tiempo, hacer preguntas abiertas y respetar su ritmo","Exigirle detalles de inmediato","Contárselo a otros por él"],0,"La paciencia y las preguntas abiertas mantienen la conversación segura."]]},
// 6 — Resiliencia y afrontamiento
{t:[
["La resiliencia se describe mejor como...",["Un rasgo fijo que algunas personas no tienen","Una habilidad que se puede aprender y fortalecer","No mostrar nunca las emociones"],1,"La resiliencia crece con habilidades de afrontamiento, apoyo y resolución de problemas."],
["¿Qué secuencia se ajusta mejor a los pasos de la resolución de problemas?",["Ignorar, esperar, olvidar","Identificar el problema, valorar opciones, probar una, buscar apoyo y reflexionar","Culpar, evitar, repetir"],1,"La resolución de problemas estructurada genera confianza."],
["Un alumno suspende un examen. ¿Qué respuesta fomenta la resiliencia?",["Decirle que no importa","Normalizar el contratiempo y ayudarle a planificar el siguiente paso","Compararle con otros"],1,"Normalizar los contratiempos y planificar el siguiente paso demuestra que es posible recuperarse."]],
a1:[
["Resiliencia significa...",["No caerse nunca","Aprender a recuperarse","Ser perfecto"],1,"Todo el mundo se cae a veces; la resiliencia es aprender a levantarse."],
["¿Cuál es un buen primer paso al resolver un problema?",["Decidir exactamente cuál es el problema","Salir corriendo","Esperar a que desaparezca"],0,"Nombrar el problema con claridad es el primer paso."],
["¿Cuál es una estrategia de afrontamiento saludable?",["Hablar con alguien, dar un paseo o respirar despacio","Evitarlo todo para siempre","Seguir enfadado"],0,"Las estrategias de afrontamiento saludables calman el cuerpo y abren opciones."]],
a2:[
["Tras un contratiempo, ¿qué enfoque muestra resolución de problemas?",["Enumerar opciones, probar una y luego evaluar lo que pasó","Rendirse de inmediato","Culpar a los demás"],0,"Probar, evaluar y ajustar es el ciclo básico."],
["¿Qué papel tiene el apoyo en la resiliencia?",["Es una señal de debilidad","Es fundamental: la resiliencia crece con la conexión","Es innecesario"],1,"El apoyo es un factor de protección, no una debilidad."],
["El desarrollo juvenil positivo se centra en...",["Corregir solo los defectos","Las fortalezas, la conexión y la contribución","Evitar los retos"],1,"Se apoya en las fortalezas y en las relaciones positivas."]]},
// 7 — Hábitos saludables
{t:[
["¿En qué cinco hábitos se centra el módulo?",["Sueño, movimiento, alimentación, atención plena y equilibrio digital","Deberes, deporte, música, arte y lectura","Dieta, videojuegos, redes sociales, compras y televisión"],0,"Estas cinco áreas influyen en el ánimo, la concentración, la energía y la resiliencia."],
["¿Cuál es el mejor enfoque en el aula respecto a los hábitos?",["Exigir rutinas perfectas","Cambios pequeños y realistas","Ignorarlos"],1,"Los cambios pequeños y constantes son más fáciles de mantener."],
["¿Cuánto sueño necesita la mayoría de los adolescentes?",["5–6 horas","8–10 horas","12–14 horas"],1,"La mayoría de los adolescentes necesita aproximadamente 8–10 horas."]],
a1:[
["¿Cuántas horas de sueño necesita la mayoría de las personas de tu edad?",["8–10","3–4","14–16"],0,"Unas 8–10 horas favorecen el ánimo y la concentración."],
["¿Qué es una pausa consciente?",["Parar un minuto para fijarte en tu respiración","Hacer scroll en silencio","Dormir en clase"],0,"Una pausa breve para notar la respiración puede calmar el cuerpo."],
["¿Qué pueden provocar las pantallas antes de dormir?",["Que cueste más dormirse","Ayudar siempre a dormir","Nada en absoluto"],0,"Prueba a relajarte sin dispositivos antes de acostarte."]],
a2:[
["¿Cuál es un cambio de hábito realista?",["Fijarte un objetivo pequeño, como pasear 10 minutos","Cambiar toda tu vida mañana","No usar nunca el móvil"],0,"Los objetivos pequeños y realistas son más fáciles de mantener."],
["¿Cómo puede afectarte dormir mal?",["Puede afectar al ánimo y a la concentración","No tiene ningún efecto","Mejora la memoria"],0,"El sueño, el ánimo y la concentración están muy relacionados."],
["Equilibrio digital significa...",["Un uso intencionado en lugar de evitarlo por completo","Borrar todas las aplicaciones","Usar el móvil todo el tiempo"],0,"Procura un uso con propósito."]]},
// 8 — Vida digital y redes sociales
{t:[
["¿Por qué muchas aplicaciones usan el scroll infinito?",["Está diseñado para retener la atención","Ahorra batería","Enseña paciencia"],0,"Las recompensas impredecibles y los contenidos sin fin nos mantienen enganchados."],
["¿Qué actividad de aula fomenta la autoconciencia algorítmica?",["Prohibir los móviles","Pedir al alumnado que observe qué muestra su feed y cómo le hace sentir","Contar seguidores"],1,"Observar los feeds y las emociones es el núcleo de la autoconciencia algorítmica."],
["¿Cuál es el mensaje más útil sobre la tecnología?",["Evitarla por completo","Fomentar un uso intencionado","Usarla más"],1,"El objetivo es una relación saludable e intencionada, no evitarla."]],
a1:[
["¿Por qué una aplicación sigue mostrando vídeos parecidos?",["El algoritmo aprende qué te mantiene mirando","Es aleatorio","Tu móvil está roto"],0,"Los algoritmos personalizan los feeds para que sigas mirando."],
["Después de hacer scroll te sientes agotado. ¿Qué ayuda?",["Tomar un descanso y elegir una actividad que te dé energía","Seguir haciendo scroll","Borrar a tus amigos"],0,"Fíjate en cómo te sientes y cambia a algo que te dé energía."],
["¿Por qué los «me gusta» y las notificaciones hacen que miremos más el móvil?",["Las recompensas impredecibles son difíciles de resistir","Son aburridos","Siempre son malos"],0,"Las recompensas impredecibles atraen nuestra atención."]],
a2:[
["¿Quiénes pueden verse más afectados por los contenidos dañinos?",["Las personas que ya son vulnerables a ellos","Nadie","Solo los adultos"],0,"Las personas vulnerables pueden verse afectadas con más intensidad."],
["¿Qué pregunta fomenta la alfabetización digital?",["¿Quién ha hecho esto y por qué me lo muestran?","¿Cuántos «me gusta» tiene?","¿Es popular?"],0,"Preguntarse por el origen y la finalidad es una habilidad básica."],
["¿Qué es un uso intencionado?",["Decidir el propósito y el tiempo antes de abrir una aplicación","Abrir aplicaciones por costumbre","Hacer scroll hasta quedarte cansado"],0,"El uso intencionado empieza con un propósito."]]},
// 9 — Identidad, cultura y pertenencia
{t:[
["¿Qué es una práctica inclusiva?",["Hacer suposiciones sobre las familias del alumnado","Usar los nombres y términos que las personas dicen usar","Pedir que compartan solo a algunos alumnos"],1,"Respetar cómo se describen las personas a sí mismas genera seguridad."],
["¿Qué significa interseccionalidad?",["Que los aspectos de la identidad interactúan y moldean la experiencia","Que solo importa la cultura","Que la identidad nunca cambia"],0,"La cultura, el género, la capacidad y la migración conforman juntos la experiencia."],
["Una alumna recién llegada se une a tu clase. ¿Qué acción favorece su pertenencia?",["Hacerla esperar","Preguntarle cómo está, incluir su cultura y hacerla sentir bienvenida","Tratarla exactamente igual sin preguntarle"],1,"Las acciones pequeñas y constantes construyen pertenencia."]],
a1:[
["La identidad está formada por...",["Muchas partes, como la cultura, el idioma, la familia y las creencias","Una sola etiqueta","Solo tus aficiones"],0,"La identidad tiene muchas capas."],
["Un compañero habla otro idioma en casa. ¿Qué es inclusivo?",["Invitarle a participar y aprender una palabra","Ignorarle","Reírte"],0,"La curiosidad y el respeto favorecen la pertenencia."],
["¿Qué construye la pertenencia?",["Las pequeñas acciones de cada día","Solo los grandes eventos","No hablar nunca"],0,"La pertenencia se construye con acciones cotidianas."]],
a2:[
["¿Qué es el estrés multicultural?",["La presión de moverse entre culturas","Unas vacaciones","Una asignatura"],0,"Las personas pueden sentirse divididas entre culturas."],
["¿Qué enfoque refleja un lenguaje inclusivo?",["Usar los términos que las personas usan para sí mismas y evitar suposiciones","Adivinar etiquetas","Evitar preguntar"],0,"Pregunta y escucha."],
["¿Qué puede provocar la exclusión repetida?",["Puede dañar la salud mental","Mejora la resiliencia","Nada"],0,"Sentirse invisible o excluido de forma repetida puede dañar el bienestar."]]},
// 10 — Hacerse grandes preguntas
{t:[
["¿Cómo pueden los valores actuar como una brújula?",["Nos guían en las decisiones cuando nos sentimos inseguros o estresados","Eliminan toda duda","Son solo para filósofos"],0,"Los valores ayudan a convertir la incertidumbre en acción con propósito."],
["¿Cómo se facilita un debate respetuoso sobre las grandes preguntas?",["Insistir en que hay una única respuesta correcta","Acoger distintos puntos de vista sin juzgar","Evitar las opiniones"],1,"El diálogo respetuoso permite que perspectivas distintas convivan."],
["Un alumno dice «¿qué sentido tiene nada?». ¿Qué es lo mejor?",["Quitarle importancia","Escuchar; si la desesperanza o los pensamientos de autolesión persisten, conectarle con apoyo","Debatir con él"],1,"Escucha con seriedad e implica al apoyo si la desesperanza persiste."]],
a1:[
["«¿Quién soy?» es...",["Una pregunta normal mientras creces","Una tontería","Solo para adultos"],0,"Las grandes preguntas son una parte natural de crecer."],
["Los valores son...",["Lo que más te importa","Solo normas de otras personas","Los ajustes de tu móvil"],0,"Los valores son lo que te importa."],
["En un debate, alguien tiene una opinión distinta. ¿Qué es respetuoso?",["Escuchar y respetar","Burlarte de él","Irte"],0,"El diálogo respetuoso explora ideas diferentes."]],
a2:[
["¿Cómo puede ayudar aclarar los valores ante la incertidumbre?",["Convierten la incertidumbre en acción con propósito","Eliminan todas las opciones","Toman las decisiones por ti"],0,"Saber qué importa facilita actuar."],
["¿Cómo puede la filosofía ser una herramienta de afrontamiento?",["Ayudándonos a examinar preguntas y ganar perspectiva","Evitando las emociones","Garantizando respuestas"],0,"Favorece la reflexión sin necesidad de una respuesta perfecta."],
["Ante una decisión difícil, ¿qué pregunta ayuda?",["¿Qué opción encaja con mis valores?","¿Cuál es la más fácil?","¿Qué piensan los demás?"],0,"Los valores actúan como una brújula."]]}
];
